 public static string EditorChecks(){Results.Clear();failed=0;var catalog=DungeonDecorationCatalog.Current;Check(catalog.entries.Length==18,"Catálogo18 prefabs reutilizables");Check(catalog.entries.Select(d=>d.id).Distinct().Count()==18,"IDs de catálogo únicos");foreach(var def in catalog.entries){Check(def.prefab.GetComponentsInChildren<Collider>().Length==0,def.id+" sin colisiones");Check(def.prefab.GetComponentsInChildren<Light>().Length==0,def.id+" sin luces dinámicas");}
  var main=DungeonMapSettings.Current;string before=JsonUtility.ToJson(main),regionsBefore=JsonUtility.ToJson(DungeonRegionSettings.Current),entitiesBefore=JsonUtility.ToJson(main.entities);var clone=UnityEngine.Object.Instantiate(main);var settings=ScriptableObject.CreateInstance<DungeonDecorationSettings>();settings.catalog=catalog;settings.regions=DungeonRegionSettings.Current;settings.automaticEnabled=true;settings.density=.30f;settings.maximumAutomatic=60;clone.decorations=settings;var state=UnityEngine.Random.state;float expectedRandom=UnityEngine.Random.value;UnityEngine.Random.state=state;var plan=DungeonDecorationPlanner.Build(clone);Check(plan.Count>0&&plan.Count<=60,"Automática genera población limitada");Check(Signature(plan)==Signature(DungeonDecorationPlanner.Build(clone)),"Misma semilla y mapa produce exactamente mismas posiciones/IDs");float actualRandom=UnityEngine.Random.value;UnityEngine.Random.state=state;Check(expectedRandom==actualRandom,"No altera RNG del combate o encuentros");settings.seed++;Check(Signature(plan)!=Signature(DungeonDecorationPlanner.Build(clone)),"Semilla distinta cambia distribución");settings.seed--;Check(plan.All(p=>DungeonDecorationPlanner.InvalidReason(clone,p,catalog.Find(p.prefabId))==null),"Automáticas válidas, interactivos y enemigos protegidos");
  string disabled=settings.regions.regions.Last().id;settings.zones.Add(new DecorationZoneRule{zoneId=disabled,enabled=false});Check(DungeonDecorationPlanner.Build(clone).All(p=>settings.regions.At(p.cell)==null||settings.regions.At(p.cell).id!=disabled),"Desactivar zona elimina sus automáticas y marcos");settings.zones.Clear();settings.density=0;Check(DungeonDecorationPlanner.Build(clone).Count==0,"Densidad0 deja todo despejado");settings.density=.30f;settings.automaticEnabled=false;Check(DungeonDecorationPlanner.Build(clone).Count==0,"Desactivar automática conserva mapa sin nuevos objetos");Check(before==JsonUtility.ToJson(main)&&regionsBefore==JsonUtility.ToJson(DungeonRegionSettings.Current)&&entitiesBefore==JsonUtility.ToJson(main.entities),"Planner no modifica mapas, zonas, encuentros o entidades originales");
  var demo=AssetDatabase.LoadAssetAtPath<DungeonMapSettings>("Assets/MapTests/DecorationShowcase/Map.asset");Check(demo.decorations.placements.All(p=>DungeonDecorationPlanner.InvalidReason(demo,p,catalog.Find(p.prefabId))==null),"Tres composiciones manuales válidas");var fixture=ScriptableObject.CreateInstance<DungeonDecorationSettings>();fixture.catalog=catalog;fixture.placements.Add(new DungeonDecorationPlacement{id="test.stable.decoration",prefabId="wall.crt",cell=new Vector2Int(3,3),heading=3});Undo.IncrementCurrentGroup();DungeonMapSettingsEditor.MoveHandleAsset(fixture,"placements.Array.data[0]","cell",new Vector2Int(3,4),false);Undo.FlushUndoRecordObjects();Check(fixture.placements[0].cell==new Vector2Int(3,4)&&fixture.placements[0].id=="test.stable.decoration","Mover conserva identidad");Undo.PerformUndo();Check(fixture.placements[0].cell==new Vector2Int(3,3),"Undo de movimiento");Undo.PerformRedo();Check(fixture.placements[0].cell==new Vector2Int(3,4),"Redo de movimiento");string path="Assets/MapTests/DecorationShowcase/PersistenceFixture.asset";if(AssetDatabase.LoadAssetAtPath<DungeonDecorationSettings>(path)==null)AssetDatabase.CreateAsset(fixture,path);else{var disk=AssetDatabase.LoadAssetAtPath<DungeonDecorationSettings>(path);EditorJsonUtility.FromJsonOverwrite(EditorJsonUtility.ToJson(fixture),disk);EditorUtility.SetDirty(disk);UnityEngine.Object.DestroyImmediate(fixture);}AssetDatabase.SaveAssets();AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);var saved=AssetDatabase.LoadAssetAtPath<DungeonDecorationSettings>(path);Check(saved.placements[0].id=="test.stable.decoration"&&saved.placements[0].cell==new Vector2Int(3,4),"Colocación persiste al guardar/importar asset");
  int validSeeds=0;settings.automaticEnabled=true;for(int i=0;i<100;i++){settings.seed=i;var generated=DungeonDecorationPlanner.Build(clone);if(generated.Count<=60&&generated.Select(p=>p.id).Distinct().Count()==generated.Count&&generated.All(p=>DungeonDecorationPlanner.InvalidReason(clone,p,catalog.Find(p.prefabId))==null))validSeeds++;}Check(validSeeds==100,"100 semillas reproducibles con límites y referencias válidas");UnityEngine.Object.DestroyImmediate(clone);UnityEngine.Object.DestroyImmediate(settings);File.WriteAllLines("Tests/DecorationEditorMcpResults.txt",Results);return string.Join("\n",Results.ToArray());
