 public static void StartPlay(){Finished=false;if(File.Exists("Tests/DecorationEditorMcpResults.txt")){Results=File.ReadAllLines("Tests/DecorationEditorMcpResults.txt").ToList();failed=Results.Count(r=>r.StartsWith("FAIL "));}var showcase=UnityEngine.Object.FindAnyObjectByType<DungeonDecorationShowcase>();showcase.StopAllCoroutines();showcase.enabled=false;var d=showcase.GetComponent<DungeonPrototype>();d.enabled=false;new GameObject("Decoration verification").AddComponent<CombatTestRunner>().StartCoroutine(Run(d,showcase));}
 static IEnumerator Run(DungeonPrototype d,DungeonDecorationShowcase showcase){var runtime=d.GetComponent<DungeonDecorationRuntime>();int count=runtime.generatedRoot.childCount;Check(count==d.mapSettings.decorations.placements.Count,"Todas las decoraciones de prueba aparecen");Check(runtime.generatedRoot.GetComponentsInChildren<Collider>().Length==0,"Instancias sin colisiones");Check(runtime.generatedRoot.GetComponentsInChildren<Light>().Length==0,"Instancias sin luces extra");Check(runtime.generatedRoot.GetComponentsInChildren<Renderer>().Any(r=>r.isPartOfStaticBatch),"Geometría estática agrupada; ventilador excluido del batching");var fan=runtime.GetComponentInChildren<DungeonDecorationMotion>();var angle=fan.rotor.localRotation;yield return new WaitForSecondsRealtime(.15f);Check(Quaternion.Angle(angle,fan.rotor.localRotation)>.1f,"Ventilador animado funciona");runtime.Rebuild();yield return null;Check(runtime.generatedRoot.childCount==count&&d.GetComponentsInChildren<DungeonDecorationRuntime>().Length==1,"Reconstruir no duplica instancias/controladores");showcase.Show(1);yield return (IEnumerator)typeof(DungeonPrototype).GetMethod("Move",F).Invoke(d,new object[]{1,0});Check((Vector2Int)typeof(DungeonPrototype).GetField("position",F).GetValue(d)==new Vector2Int(9,6),"Movimiento real atraviesa casilla con conducto sin bloqueo");d.PrepareDecorationPreview(new Vector2Int(11,19),0);yield return (IEnumerator)typeof(DungeonPrototype).GetMethod("Move",F).Invoke(d,new object[]{1,0});Check((Vector2Int)typeof(DungeonPrototype).GetField("position",F).GetValue(d)==new Vector2Int(11,20),"Movimiento real sobre placa decorativa permitido");var save=d.CaptureDungeonSave();d.RestoreDungeonSave(JsonUtility.FromJson<DungeonSaveData>(JsonUtility.ToJson(save)));yield return null;Check(runtime.generatedRoot.childCount==count,"Carga de partida no duplica decoración del mapa");Check(DungeonSaveStore.editorTestPath=="Tests/DecorationShowcaseFixture.json","Partidas personales aisladas durante demostración");Results.Add("TOTAL "+(Results.Count-failed)+" PASS / "+failed+" FAIL");Directory.CreateDirectory("Tests");File.WriteAllLines("Tests/DecorationMcpResults.txt",Results);d.enabled=showcase.enabled=true;showcase.Show(0);Finished=true;}
